## Delete uploaded files  {% id="delete-uploaded" %}

Files are automatically deleted after 48 hours. You can also manually delete an
uploaded file:

{% tabs %}
  {% tab label="Python" %}
  ```python
  from google import genai

  client = genai.Client()

  myfile = client.files.upload(file='path/to/sample.mp3')
  client.files.delete(name=myfile.name)
  ```

  {% /tab %}

  {% tab label="JavaScript" %}
  ```javascript
  import {
    GoogleGenAI,
  } from "@google/genai";

  const client = new GoogleGenAI({});

  async function main() {
    const myfile = await client.files.upload({
      file: "path/to/sample.mp3",
      config: { mimeType: "audio/mpeg" },
    });

    const fileName = myfile.name;
    await client.files.delete({ name: fileName || '' });
  }

  await main();
  ```

  {% /tab %}

  {% tab label="Java" %}
  ```java
  import com.google.genai.Client;
  import com.google.genai.types.File;
  import com.google.genai.types.UploadFileConfig;

  Client client = new Client();

  File myFile =
      client.files.upload(
          new java.io.File("path/to/sample.mp3"),
          UploadFileConfig.builder().mimeType("audio/mp3").build());

  client.files.delete(myFile.name().orElse(""), null);
  ```

  {% /tab %}

  {% tab label="Go" %}
  ```go
  package main

  import (
      "context"
      "log"

      "google.golang.org/genai"
  )

  func main() {
      ctx := context.Background()
      client, err := genai.NewClient(ctx, nil)
      if err != nil {
          log.Fatal(err)
      }

      myFile, err := client.Files.UploadFromPath(ctx, "path/to/sample.mp3", &genai.UploadFileConfig{
          MIMEType: "audio/mp3",
      })
      if err != nil {
          log.Fatal(err)
      }

      if _, err := client.Files.Delete(ctx, myFile.Name, nil); err != nil {
          log.Fatal(err)
      }
  }
  ```

